package app.yoru.mobile;

import android.app.*;
import android.content.pm.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.media3.common.*;
import androidx.media3.exoplayer.*;
import androidx.media3.exoplayer.source.DefaultMediaSourceFactory;
import androidx.media3.ui.PlayerView;
import java.util.*;

public final class ClipFeedActivity extends Activity {
    private FrameLayout root;private PlayerView video;private ExoPlayer player;private LinearLayout loading,info;private TextView title,meta,like,status;private final Handler timer=new Handler(Looper.getMainLooper());private final Random random=new Random();private final ArrayList<Anime> pool=new ArrayList<>();private final ArrayDeque<Clip> history=new ArrayDeque<>();private Clip current,next;private boolean destroyed,loadingNext,prepared,waitingNext;private float downY;private long endMs;private int generation;
    private static final class Clip {Anime anime;double episode;String url="",voice="";int quality,start,length,duration;}
    private final Runnable tick=new Runnable(){public void run(){if(destroyed)return;if(current!=null&&prepared&&player!=null&&player.isPlaying()&&endMs>0&&player.getCurrentPosition()>=endMs)showNext();timer.postDelayed(this,500);}};
    @Override public void onCreate(Bundle b){super.onCreate(b);if(!Ui.allow(this))return;getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_SENSOR_PORTRAIT);build();makePool();loadFirst();timer.postDelayed(tick,500);}
    private void build(){root=new FrameLayout(this);root.setBackgroundColor(Color.BLACK);setContentView(root);DefaultLoadControl control=new DefaultLoadControl.Builder().setBufferDurationsMs(2500,8500,400,900).setBackBuffer(0,false).build();player=new ExoPlayer.Builder(this).setLoadControl(control).build();video=new PlayerView(this);video.setPlayer(player);video.setUseController(false);video.setResizeMode(androidx.media3.ui.AspectRatioFrameLayout.RESIZE_MODE_ZOOM);video.setBackgroundColor(Color.BLACK);root.addView(video,new FrameLayout.LayoutParams(-1,-1));View shade=new View(this);shade.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x66000000,0x00000000,0xdd000000}));root.addView(shade,new FrameLayout.LayoutParams(-1,-1));FrameLayout top=new FrameLayout(this);top.setPadding(Ui.dp(this,14),Ui.dp(this,22),Ui.dp(this,14),0);TextView label=Ui.text(this,"YORU Clips",16,Ui.TEXT,true);label.setGravity(Gravity.CENTER);top.addView(label,new FrameLayout.LayoutParams(-1,Ui.dp(this,42),Gravity.TOP));FrameLayout.LayoutParams backLp=new FrameLayout.LayoutParams(Ui.dp(this,42),Ui.dp(this,42),Gravity.LEFT|Gravity.TOP);top.addView(Ui.iconButton(this,"back","Назад",this::finish),backLp);root.addView(top,new FrameLayout.LayoutParams(-1,Ui.dp(this,80),Gravity.TOP));info=Ui.column(this);info.setPadding(Ui.dp(this,16),0,Ui.dp(this,88),Ui.dp(this,24));title=Ui.text(this,"Загружаем фрагмент…",22,Color.WHITE,true);title.setMaxLines(3);info.addView(title);Ui.space(info,8);meta=Ui.text(this,"Только текущий клип и следующий в очереди",12,0xffdacde8,false);info.addView(meta);Ui.space(info,8);status=Ui.text(this,"",11,0xffbdaed0,false);info.addView(status);FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);root.addView(info,ip);LinearLayout side=Ui.column(this);side.setGravity(Gravity.CENTER);like=Ui.text(this,"♡\nЛайк",12,Color.WHITE,true);like.setGravity(Gravity.CENTER);like.setPadding(Ui.dp(this,8),Ui.dp(this,9),Ui.dp(this,8),Ui.dp(this,9));like.setBackground(Ui.shape(0x66000000,18,this));like.setOnClickListener(v->likeCurrent());side.addView(like,Ui.lp(this,64,64));Ui.space(side,12);TextView open=Ui.text(this,"▶\nСерия",12,Color.WHITE,true);open.setGravity(Gravity.CENTER);open.setPadding(Ui.dp(this,8),Ui.dp(this,9),Ui.dp(this,8),Ui.dp(this,9));open.setBackground(Ui.shape(0x66000000,18,this));open.setOnClickListener(v->openCurrent());side.addView(open,Ui.lp(this,64,64));Ui.space(side,12);TextView nextButton=Ui.text(this,"↑\nДальше",12,Color.WHITE,true);nextButton.setGravity(Gravity.CENTER);nextButton.setPadding(Ui.dp(this,8),Ui.dp(this,9),Ui.dp(this,8),Ui.dp(this,9));nextButton.setBackground(Ui.shape(0x66000000,18,this));nextButton.setOnClickListener(v->showNext());side.addView(nextButton,Ui.lp(this,64,64));FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(Ui.dp(this,76),-2,Gravity.RIGHT|Gravity.CENTER_VERTICAL);sp.rightMargin=Ui.dp(this,8);root.addView(side,sp);loading=Ui.column(this);loading.setGravity(Gravity.CENTER);loading.setBackgroundColor(0xaa000000);ProgressBar bar=new ProgressBar(this);loading.addView(bar,Ui.lp(this,42,42));Ui.space(loading,12);loading.addView(Ui.text(this,"Ищем клип…",12,0xffdacde8,true));root.addView(loading,new FrameLayout.LayoutParams(-1,-1));root.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){downY=e.getY();return true;}if(e.getAction()==MotionEvent.ACTION_UP){float dy=e.getY()-downY;if(dy<-Ui.dp(this,70)){showNext();return true;}if(dy>Ui.dp(this,90)){showPrevious();return true;}openCurrent();return true;}return true;});player.addListener(new Player.Listener(){@Override public void onPlaybackStateChanged(int state){if(state==Player.STATE_READY){loading.setVisibility(View.GONE);prepared=true;long d=player.getDuration();if(current!=null){if(d!=C.TIME_UNSET&&d>35000){current.duration=(int)(d/1000);if(current.start*1000L>d-18000){current.start=Math.max(0,(int)(d/1000)-current.length-8);player.seekTo(current.start*1000L);}}endMs=(current.start+current.length)*1000L;status.setText(Ui.time(current.start)+"–"+Ui.time(current.start+current.length)+" · свайп вверх для следующего");}player.play();ensureNext();}else if(state==Player.STATE_ENDED)showNext();}@Override public void onPlayerError(PlaybackException error){showNext();}});}
    private void makePool(){LinkedHashMap<String,Anime> map=new LinkedHashMap<>();for(Anime a:YoruApp.app().store.recent())if(Anime.valid(a))map.put(a.key(),a);for(Anime a:YoruApp.app().store.favorites())if(Anime.valid(a))map.put(a.key(),a);for(Anime a:YoruApp.app().api.seed())if(Anime.valid(a))map.put(a.key(),a);pool.addAll(map.values());Collections.shuffle(pool);}
    private void loadFirst(){loading.setVisibility(View.VISIBLE);status.setText("Лента включается только сейчас — фоновых загрузок нет.");YoruApp.app().io.execute(()->{Clip c=null;for(int i=0;i<18&&c==null;i++)c=makeClip();Clip ready=c;YoruApp.app().main.post(()->{if(destroyed)return;if(ready==null){loading.setVisibility(View.GONE);Ui.toast(this,"Пока не удалось собрать клип");return;}play(ready);});});}
    private Clip makeClip(){if(pool.isEmpty())makePool();if(pool.isEmpty())return null;Anime base=pool.get(random.nextInt(pool.size()));try{Anime.Playback ready=YoruApp.app().api.playback(base,"yoru");if(ready==null||ready.video==null||ready.video.episodeList.isEmpty())return null;ArrayList<Anime.Episode> episodes=new ArrayList<>(ready.video.episodeList);Anime.Episode ep=episodes.get(Math.abs(random.nextInt())%episodes.size());YoruApp.app().api.loadEpisode(ep);TreeMap<Integer,String> streams=new TreeMap<>();String voice="";if(!ep.streams.isEmpty()){streams.putAll(ep.streams);voice=ApiRepository.sourceVoice(ready.video.source);}else if(!ep.variants.isEmpty()){Anime.Variant v=SourceEngine.sortVariants(ep.variants).get(0);voice=ApiRepository.voiceTitle(v.name.isEmpty()?v.label():v.name);streams=YoruApp.app().api.resolveStreams(v.url);}if(streams.isEmpty())return null;int target=YoruApp.app().savingMobile()?480:YoruApp.app().store.quality(),quality=streams.firstKey();for(Integer q:streams.keySet())if(q!=null&&q>0&&q<=target)quality=q;String url=ApiRepository.safeUrl(streams.get(quality));if(url.isEmpty())return null;Clip c=new Clip();c.anime=ready.catalog==null?base:ready.catalog;c.episode=ep.number;c.url=url;c.voice=voice;c.quality=quality;c.duration=ep.duration;c.length=15+random.nextInt(16);int safeDuration=c.duration>90?c.duration:22*60;int max=Math.max(0,safeDuration-c.length-20);c.start=max<=35?0:20+random.nextInt(Math.max(1,max-20));return c;}catch(Exception e){return null;}}
    private void play(Clip clip){if(clip==null)return;if(current!=null)history.push(current);while(history.size()>12)history.removeLast();current=clip;prepared=false;waitingNext=false;endMs=0;generation++;loading.setVisibility(View.VISIBLE);player.stop();title.setText(YoruBrain.title(clip.anime));String voice=ApiRepository.voiceTitle(clip.voice);meta.setText("Серия "+Ui.number(clip.episode)+(voice.isEmpty()?"":" · "+voice)+(clip.quality>0?" · "+clip.quality+"p":""));like.setText(YoruApp.app().store.favorite(clip.anime)?"♥\nВ избранном":"♡\nЛайк");player.setTrackSelectionParameters(player.getTrackSelectionParameters().buildUpon().setMaxVideoSize(Integer.MAX_VALUE,YoruApp.app().savingMobile()?480:Integer.MAX_VALUE).setForceLowestBitrate(YoruApp.app().savingMobile()).build());player.setMediaSource(new DefaultMediaSourceFactory(YoruApp.app().mediaCache.onlineFactory()).createMediaSource(DownloadHub.item(clip.url)));player.prepare();if(clip.start>0)player.seekTo(clip.start*1000L);player.play();}
    private void ensureNext(){if(destroyed||loadingNext||next!=null)return;loadingNext=true;int gen=generation;YoruApp.app().io.execute(()->{Clip c=null;for(int i=0;i<14&&c==null;i++)c=makeClip();Clip ready=c;YoruApp.app().main.post(()->{loadingNext=false;if(destroyed||gen!=generation)return;next=ready;if(waitingNext&&next!=null){waitingNext=false;showNext();}});});}
    private void showNext(){if(destroyed)return;if(next!=null){Clip ready=next;next=null;play(ready);ensureNext();return;}waitingNext=true;if(player!=null)player.pause();loading.setVisibility(View.VISIBLE);status.setText("Грузим следующий клип…");ensureNext();timer.postDelayed(()->{if(!destroyed&&next!=null){waitingNext=false;showNext();}else if(!destroyed)status.setText("Ещё ищем рабочий фрагмент…");},900);}
    private void showPrevious(){Clip prev=history.poll();if(prev!=null)play(prev);}
    private void likeCurrent(){if(current==null)return;YoruApp.app().store.favorite(current.anime,"planned");like.setText("♥\nВ избранном");Ui.toast(this,"Добавлено в коллекцию");}
    private void openCurrent(){if(current==null)return;Ui.openPlayer(this,current.anime,"yoru",current.episode);}
    @Override protected void onPause(){super.onPause();if(player!=null)player.pause();}
    @Override protected void onResume(){super.onResume();if(player!=null&&current!=null)player.play();}
    @Override protected void onDestroy(){destroyed=true;timer.removeCallbacksAndMessages(null);getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(player!=null)player.release();super.onDestroy();}
}
